import{z as s,x as B,o as e,c as n,q as A,j as r,D as E,d as t,s as l,S as i}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"SLO 工程","description":"","frontmatter":{"title":"SLO 工程","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/obs-slo-engineering.md","filePath":"cs/obs-slo-engineering.md","lastUpdated":1791413859000}'),d={name:"cs/obs-slo-engineering.md"};function p(S,a,_,h,c,m){const o=B("Mermaid");return e(),n("div",null,[a[2]||(a[2]=A('<h1 id="slo-工程" tabindex="-1">SLO 工程 <a class="header-anchor" href="#slo-工程" aria-label="Permalink to &quot;SLO 工程&quot;">​</a></h1><div class="epigraph"><p>SLO 不是承诺接近百分之百，是选择在哪里主动花掉不完美：错误预算把「可靠」从愿望变成一笔可以花的钱。</p><footer>—— 据 Google SRE 书（Beyer et al., 2016）第 3-4 章与 SRE Workbook（2018）第 5-6 章整理</footer></div><p><a href="/cs/obs-distributed-tracing">上一课</a>给了单次请求的完整树：这一次哪里慢、哪里错。缺口在聚合层：全体流量对用户够不够好，以及不够好时，组织该把工程时间投给新功能还是可靠性债。<a href="/cs/observability-pillars">可观测三支柱</a>只用一句话带过「SLO 用指标定义错误预算」；本课把它展开成工程：SLI 的选法、预算的算法、烧速告警的数学、预算政策怎么长出牙齿。后课事故指挥默认已读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一条「月均可用性 99.9%」为什么不够：平均掩盖长尾——一部分用户可以永远处在坏的那 0.1% 里，均值却达标；日历月窗口让月初躺平、月末狂修；没有配套政策的 SLO 只是墙上的标语，超了也没人停手。工程缺口四件：SLI 要从用户旅程出发——「请求成功且在 300 毫秒内返回」，而不是「CPU 低于 80%」这类机器舒服、用户遭罪的代理指标；窗口要用滚动的，让预算每天等速补回；错误预算 \\(1-\\mathrm{SLO}\\) 要有明确的账本，谁在花、花了多少；预算烧完要有自动后果，否则不是 SLO 是许愿。</p><h3 id="从-sli-到预算" tabindex="-1">从 SLI 到预算 <a class="header-anchor" href="#从-sli-到预算" aria-label="Permalink to &quot;从 SLI 到预算&quot;">​</a></h3><p>SLI 定义为好事件除以总事件，在滚动窗口上聚合；延迟分位数用第一课钉过的直方图纪律取，桶太疏分位数就失真。测量点离用户越近越真：前端实测优于服务端代理，服务端代理优于 SLA 报表。错误预算就是允许的坏：SLO 99.9% 等于 28 天窗口里允许 0.1% 的请求失败——这笔钱要么花在故障上，要么主动花在激进发布上，总之要记账。</p>',7)),(e(),r(i,null,{default:E(()=>[l(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20SLI%5B%22%E5%A5%BD%E4%BA%8B%E4%BB%B6%20%2F%20%E6%80%BB%E4%BA%8B%E4%BB%B6%EF%BC%8C%E6%BB%9A%E5%8A%A8%E7%AA%97%22%5D%20--%3E%20BUD%5B%22%E9%94%99%E8%AF%AF%E9%A2%84%E7%AE%97%20%3D%201%20-%20SLO%22%5D%0A%20%20BUD%20--%3E%20BURN%7B%22%E7%83%A7%E9%80%9F%20%3D%20%E5%AE%9E%E9%99%85%E9%94%99%E8%AF%AF%E7%8E%87%20%2F%20%E5%85%81%E8%AE%B8%E9%94%99%E8%AF%AF%E7%8E%87%22%7D%0A%20%20BURN%20--%3E%7C%22%E9%95%BF%E7%AA%97%E5%8A%A0%E7%9F%AD%E7%AA%97%E5%90%8C%E6%97%B6%E8%B6%85%E7%BA%BF%22%7C%20PAGE%5B%22%E5%91%BC%E4%BA%BA%22%5D%0A%20%20BURN%20--%3E%7C%22%E7%BC%93%E6%85%A2%E6%B6%88%E8%80%97%22%7C%20TICKET%5B%22%E5%BB%BA%E5%8D%95%E5%A4%84%E7%90%86%22%5D%0A%20%20BUD%20--%3E%7C%22%E9%A2%84%E7%AE%97%E7%83%A7%E5%B0%BD%22%7C%20FREEZE%5B%22%E5%86%BB%E7%BB%93%E5%8A%9F%E8%83%BD%E5%8F%91%E5%B8%83%EF%BC%8C%E8%BF%98%E5%8F%AF%E9%9D%A0%E6%80%A7%E5%80%BA%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A('<p><span class="marginnote">SRE Workbook 的经典烧速配置：14.4 倍烧速叠 1 小时加 5 分钟双窗，1 小时内烧掉 2% 的月预算；6 倍烧速叠 6 小时加 30 分钟，6 小时烧掉 5%。长窗保「值得叫醒人」，短窗保「发现得早」。</span></p><p><span class="marginnote">数字实例：99.9% 的 SLO 在 28 天窗口里的错误预算是 0.1%，换算下来约 40 分钟的「坏」可以花。这 40 分钟要么被故障被动烧掉，要么主动花在激进发布上——所以它是预算，不是口号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>告警不用静态阈值而用烧速：burn rate 定义为实际错误率对允许错误率之比，等于 1 表示预算恰好 28 天烧完。多窗双确认——长窗加短窗同时超线才呼人——单短窗对毛刺过敏，单长窗迟到一小时；两个独立窗口同时过线，滤掉绝大多数单点抖动。政策写出牙齿：预算烧尽自动冻结功能发布进流水线闸门，优先还可靠性债；预算充裕则允许激进发布。没有闸门的政策会退化成报表，因为「冻结」落在人的自觉上时，发布压力总能赢。依赖链要摊预算：上游 99.9% 串下游 99.9%，端到端约 99.8%——预算按依赖树分配，别把整笔钱留给最外层。</p><p><span class="marginnote">直觉类比：错误预算像每月零花钱——定额固定，乱花（故障）完了这个月就得停止买新东西（冻结发布），专心还债（修可靠性）；这个月省着花，下个月额度照常恢复（滚动窗口）。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么烧速在数学上优于阈值：恒定 0.05% 的错误率在 0.1% 预算下永不超阈值也不该呼人（预算正好撑满窗口），静态阈值要么对此误报要么对尖峰漏报；烧速把「预算消耗速度」本身变成信号，低速率天然安静，高速率天然响。为什么双窗能降噪：把毛刺同时骗过两个时间尺度，概率是单窗误报率的乘积量级。为什么预算冻结可执行：发布走流水线，闸门查预算余量是机器能做的判断，与「指标吃基数预算」同构——预算制的本质是把稀缺资源变成先登记后消费。为什么分位数延迟要用直方图而不是平均：平均响应达标而第 99 百分位翻倍的服务，用户体验已经坏掉，SLO 的分母错一半。</p><p><span class="marginnote">常见误区：初学者以为 SLO 定得越接近 100% 越好。100% 意味着错误预算为零——任何发布、任何变更都立刻违规，团队只能躺平不动。SLO 的本质不是追求完美，是选择把不完美主动花在哪里。</span></p>',8)),(e(),r(i,null,{default:E(()=>[l(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E7%94%A8%E6%88%B7%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20A%5B%22%E7%BD%91%E5%85%B3%20%E5%8F%AF%E7%94%A8%E6%80%A7%2099.9%25%22%5D%0A%20%20A%20--%3E%20B%5B%22%E6%9C%8D%E5%8A%A1%20%E5%8F%AF%E7%94%A8%E6%80%A7%2099.9%25%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%95%B0%E6%8D%AE%E5%BA%93%20%E5%8F%AF%E7%94%A8%E6%80%A7%2099.9%25%22%5D%0A%20%20C%20--%3E%20E%5B%22%E7%AB%AF%E5%88%B0%E7%AB%AF%E7%BA%A6%2099.7%25%20%E4%B8%B2%E8%A1%8C%E7%9B%B8%E4%B9%98%22%5D%0A%20%20E%20--%3E%20F%5B%22%E9%A2%84%E7%AE%97%E6%8C%89%E4%BE%9D%E8%B5%96%E6%A0%91%E6%91%8A%E9%85%8D%20%E4%B8%8D%E5%85%A8%E7%95%99%E7%BB%99%E6%9C%80%E5%A4%96%E5%B1%82%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 SLA 的法务与赔偿条款，那是商务合同；不展开数据新鲜度、正确性这类非延迟非可用性的 SLO 变体，只点名它们同构。也不重讲指标基数与直方图实现——第一课的账直接复用。SLO 把「什么时候该呼人」变成了数学，但呼了之后人在肾上腺素里怎么协作，数学不管——下一课事故指挥。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SLI 从用户旅程定义：好事件/总事件，滚动窗聚合。</li><li>错误预算 \\(1-\\mathrm{SLO}\\) 是可花的钱，要有账本与政策。</li><li>告警用烧速加多窗双确认，长窗定性、短窗及时。</li><li>预算烧尽的后果要落在流水线闸门上，不是口头纪律。</li><li>依赖链串行吃预算，按依赖树摊配。</li><li>出处：Google SRE 书（2016）第 3-4 章；SRE Workbook（2018）第 5-6 章的烧速告警口径。</li></ul>',4))])}const C=s(d,[["render",p]]);export{F as __pageData,C as default};
